'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { DOCUMENT_REQUIREMENTS, type VendorDocumentRecord, vendorDocumentService } from '@/lib/vendor/documents'
import { CatalogFeedback } from '../components/CatalogFeedback'
import { DocumentCard } from '../components/DocumentCard'

export default function VendorDocumentsPage() { const [vendorId, setVendorId] = useState<string | null>(null); const [documents, setDocuments] = useState<VendorDocumentRecord[]>([]); const [loading, setLoading] = useState(true); const [message, setMessage] = useState(''); useEffect(() => { void createClient().auth.getUser().then(async ({ data: { user } }) => { if (user && (getUserRole(user) === 'vendor' || getUserRole(user) === 'admin')) { setVendorId(user.id); setDocuments(await vendorDocumentService.list(user.id)) } setLoading(false) }) }, []); async function upload(requirementId: string, file: File) { if (!vendorId) return; const existing = documents.find((document) => document.requirementId === requirementId); if (existing?.fileName) await vendorDocumentService.replace(vendorId, existing.id, file); else await vendorDocumentService.upload(vendorId, requirementId, file); setDocuments(await vendorDocumentService.list(vendorId)); setMessage('Document staged successfully. It will remain pending until verification is connected.') } if (loading) return <main className="vendor-page"><div className="operations-shell"><CatalogFeedback type="loading">Loading documents...</CatalogFeedback></div></main>; return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor" className="btn-skip">Portal</Link><span className="vendor-header-label">Documents</span></nav></header><div className="operations-shell"><div className="operations-heading"><div><p className="vendor-eyebrow">Vendor operations</p><h1>Documents</h1><p>Keep required business and compliance documents current for marketplace verification.</p></div><Link href="/vendor" className="btn-skip">Onboarding</Link></div>{message ? <div className="operations-success" role="status">{message}</div> : null}<div className="document-grid">{DOCUMENT_REQUIREMENTS.map((requirement) => { const document = documents.find((item) => item.requirementId === requirement.id); return document ? <DocumentCard key={requirement.id} requirement={requirement} document={document} onUpload={(file) => void upload(requirement.id, file)} /> : null })}</div><p className="operations-note">Required document types are configurable. File contents and verification decisions will move to the document API and private storage service.</p></div></main> }